package java.util;
public final class StringJoiner {private final String delimiter,prefix,suffix;private String emptyValue;private StringBuilder value;public StringJoiner(CharSequence d){this(d,"","");}public StringJoiner(CharSequence d,CharSequence p,CharSequence s){delimiter=Objects.requireNonNull(d).toString();prefix=Objects.requireNonNull(p).toString();suffix=Objects.requireNonNull(s).toString();emptyValue=prefix+suffix;}public StringJoiner setEmptyValue(CharSequence e){emptyValue=Objects.requireNonNull(e).toString();return this;}public StringJoiner add(CharSequence e){if(value==null)value=new StringBuilder();else value.append(delimiter);value.append(e);return this;}public StringJoiner merge(StringJoiner other){Objects.requireNonNull(other);if(other.value!=null)add(other.value);return this;}public int length(){return value==null?emptyValue.length():prefix.length()+value.length()+suffix.length();}public String toString(){return value==null?emptyValue:prefix+value.toString()+suffix;}}
